def gen(rng):
    def build(pairs, single):
        a = []
        for v in pairs:
            a += [v, v]
        a.append(single)
        rng.shuffle(a)
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    def distinct(k, lo, hi):
        s = set()
        while len(s) < k:
            s.add(rng.randint(lo, hi))
        return list(s)
    tests = ['1\n0', '1\n-1000000000', '3\n5 5 -7', '3\n1000000000 -1000000000 1000000000']
    for k in (1, 2, 3, 5, 8, 12, 20):
        for _ in range(2):
            vals = distinct(k + 1, -30, 30)
            tests.append(build(vals[:k], vals[k]))
    for k in (4, 9):
        vals = distinct(k + 1, -10**9, 10**9)
        tests.append(build(vals[:k], vals[k]))
    K = 49999
    vals = distinct(K + 1, -10**9, 10**9)
    tests.append(build(vals[:K], vals[K]))
    vals = distinct(K + 1, 0, 200000)
    tests.append(build(vals[:K], vals[K]))
    vals = distinct(K + 1, -10**9, -10**9 + 200000)
    tests.append(build(vals[:K], vals[K]))
    return tests
